:root{--db-bg:#0b0d12;--db-card:#11151d;--db-line:#252c38;--db-text:#f4f7fb;--db-muted:#94a3b8;--db-cyan:#00b8d9}body{background:var(--db-bg);color:var(--db-text);font-family:'Plus Jakarta Sans',Arial,sans-serif;margin:0}.db-shell{max-width:1440px;margin:auto;display:grid;grid-template-columns:240px minmax(0,1fr);min-height:100vh}.db-side{padding:25px 18px;border-right:1px solid var(--db-line);background:#0e1118}.db-brand{font-size:25px;font-weight:800;letter-spacing:-1px;margin-bottom:34px}.db-brand span{color:var(--db-cyan)}.db-nav{display:grid;gap:8px}.db-nav a{padding:12px 14px;border-radius:10px;color:#b7c2d2;text-decoration:none}.db-nav a.active,.db-nav a:hover{background:#123b7a55;color:white}.db-side small{color:var(--db-muted)}.db-side-card{border:1px solid var(--db-line);border-radius:14px;padding:14px;margin-top:25px;font-size:13px}.db-side-card a{color:var(--db-cyan)}.db-main{min-width:0}.db-top{display:flex;align-items:center;justify-content:space-between;gap:15px;padding:18px 28px;border-bottom:1px solid var(--db-line);position:sticky;top:0;background:#0b0d12ee;backdrop-filter:blur(10px);z-index:2}.db-top a{color:var(--db-muted);text-decoration:none}.db-content{max-width:1100px;margin:0 auto;padding:30px}.db-head{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;margin-bottom:24px}.db-head h1{margin:0 0 8px;font-size:clamp(25px,3vw,34px)}.db-muted{color:var(--db-muted);line-height:1.55}.db-card{background:var(--db-card);border:1px solid var(--db-line);border-radius:16px;padding:20px;margin-bottom:16px;min-width:0}.db-card h2,.db-card h3{margin-top:0}.db-grid{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(250px,1fr);gap:18px}.db-form{display:grid;gap:12px}.db-form label{display:grid;gap:7px;color:#cbd5e1;font-size:13px}.db-form input,.db-form textarea,.db-form select{box-sizing:border-box;width:100%;padding:12px;border:1px solid #303948;background:#0b0f16;color:white;border-radius:10px;font:inherit}.db-form textarea{min-height:95px;resize:vertical}.db-btn{display:inline-flex;align-items:center;justify-content:center;border:0;border-radius:9px;background:var(--db-cyan);color:#04121a!important;text-decoration:none;font-weight:800;padding:10px 14px;cursor:pointer;font:inherit;font-size:13px}.db-btn.secondary{background:#202938;color:#e5edf7!important}.db-btn.danger{background:#7f1d1d;color:#fee2e2!important}.db-inline{display:inline}.db-row{display:flex;align-items:center;gap:12px;justify-content:space-between;flex-wrap:wrap}.db-name{font-weight:750}.db-small{font-size:12px;color:var(--db-muted)}.db-tags{display:flex;gap:7px;flex-wrap:wrap;margin:10px 0}.db-tag{background:#17202d;border:1px solid #2b3545;color:#b9d9e7;padding:5px 9px;border-radius:7px;font-size:12px}.db-alert{padding:12px 15px;border-radius:10px;background:#064e3b55;color:#a7f3d0;border:1px solid #10b98166;margin-bottom:16px}.db-alert.error{background:#7f1d1d44;color:#fecaca;border-color:#ef444466}.db-divider{border:0;border-top:1px solid var(--db-line);margin:16px 0}.db-comments{margin-top:12px;padding-top:10px;border-top:1px solid var(--db-line)}.db-comment{padding:8px 0;color:#cbd5e1}.db-message{max-width:80%;padding:10px 13px;border-radius:12px;margin:8px 0;background:#202938}.db-message.mine{margin-left:auto;background:#123b7a}.db-list{display:grid;gap:10px}.db-item{padding:13px;border:1px solid var(--db-line);border-radius:12px}.db-link{color:var(--db-cyan);overflow-wrap:anywhere}.db-two{display:grid;grid-template-columns:1fr 1fr;gap:12px}.db-empty{padding:24px;text-align:center;color:var(--db-muted)}@media(max-width:850px){.db-shell{grid-template-columns:1fr}.db-side{border-right:0;border-bottom:1px solid var(--db-line);padding:15px}.db-brand{margin-bottom:12px}.db-nav{display:flex;flex-wrap:wrap}.db-nav a{padding:8px 10px}.db-side-card{display:none}.db-grid{grid-template-columns:1fr}.db-content{padding:18px}.db-top{padding:14px 18px;position:static}.db-two{grid-template-columns:1fr}}
</style></head><body><div class="db-shell"><aside class="db-side"><div class="db-brand">◉ dev<span>bolha</span></div><nav class="db-nav"><a class="<?=$page==='feed'?'active':''?>" href="?page=feed">⌂ Feed</a><a class="<?=$page==='perfil'?'active':''?>" href="?page=perfil">♙ Meu perfil</a><a class="<?=$page==='conexoes'?'active':''?>" href="?page=conexoes">♧ Conexões</a><a class="<?=$page==='mensagens'?'active':''?>" href="?page=mensagens">▤ Mensagens</a><a class="<?=$page==='projetos'?'active':''?>" href="?page=projetos">⌘ Projetos</a><?php if($eu['tipo_usuario']==='administrador'):?><a class="<?=$page==='admin'?'active':''?>" href="?page=admin">⚙ Administração</a><?php endif;?></nav><div class="db-side-card"><b>Convide seus amigos</b><p>Você pode compartilhar convites com novos membros.</p><a href="?page=perfil">Ver meus convites ↗</a></div></aside><div class="db-main"><header class="db-top"><div><span class="db-small">COMUNIDADE / </span><b><?=h(['feed'=>'Feed','perfil'=>'Meu perfil','conexoes'=>'Conexões','mensagens'=>'Mensagens','notificacoes'=>'Notificações','projetos'=>'Projetos','admin'=>'Administração'][$page])?></b></div><div class="db-row"><a href="?page=perfil"><?=h($eu['nome'].' '.$eu['sobrenome'])?></a><a href="?page=notificacoes" title="Notificações">Notificações (<?=$notificacoesPendentes?>)</a><a href="logout.php">Sair ↗</a></div></header><main class="db-content"><div class="db-head"><div><h1><?=h(['feed'=>'Seu espaço para construir.','perfil'=>'Seu perfil profissional.','conexoes'=>'Construa sua rede.','mensagens'=>'Conversas que conectam.','notificacoes'=>'Acompanhe as novidades.','projetos'=>'Projetos que movem.','admin'=>'Painel administrativo.'][$page])?></h1><div class="db-muted"><?=h(['feed'=>'Compartilhe aprendizados e acompanhe a comunidade.','perfil'=>'Mostre suas habilidades e o que você quer construir.','conexoes'=>'Gerencie solicitações e encontre outros membros.','mensagens'=>'Converse com suas conexões aceitas.','notificacoes'=>'Solicitações, curtidas, comentários e mensagens em um só lugar.','projetos'=>'Encontre iniciativas e participe de projetos reais.','admin'=>'Acompanhe denúncias e ferramentas de moderação.'][$page])?></div></div></div>
