<?php if($page==='feed'): ?>
<div class="db-grid"><section><div class="db-card"><h2>Compartilhe com a comunidade</h2><form class="db-form" method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="acao" value="publicar"><label>O que você está construindo?<textarea name="texto" maxlength="10000" placeholder="Compartilhe um aprendizado, uma ideia ou o progresso de um projeto..."></textarea></label><label>Link externo (opcional)<input type="url" name="link_externo" placeholder="https://github.com/seu-projeto"></label><button class="db-btn" type="submit">Publicar ↗</button></form></div>
<?php $st=$pdo->query("SELECT p.*,u.nome,u.sobrenome,u.tipo_usuario,(SELECT COUNT(*) FROM curtidas c WHERE c.id_publicacao=p.id_publicacao) total_curtidas,(SELECT COUNT(*) FROM comentarios cm WHERE cm.id_publicacao=p.id_publicacao) total_comentarios,(SELECT COUNT(*) FROM curtidas c2 WHERE c2.id_publicacao=p.id_publicacao AND c2.id_usuario=".$id.") curtiu FROM publicacoes p LEFT JOIN usuarios u ON u.id_usuario=p.id_usuario WHERE p.status_publicacao='publicada' ORDER BY p.data_criacao DESC LIMIT 50");$posts=$st->fetchAll();foreach($posts as $p):?><article class="db-card"><div class="db-row"><div><div class="db-name"><?=h(trim(($p['nome']??'Membro removido').' '.($p['sobrenome']??'')))?></div><div class="db-small"><?=h(e_data($p['data_criacao']))?></div></div></div><?php if($p['texto']!==''):?><p style="white-space:pre-wrap;overflow-wrap:anywhere"><?=h($p['texto'])?></p><?php endif;?><?php if($p['link_externo']):?><p><a class="db-link" href="<?=h($p['link_externo'])?>" target="_blank" rel="noopener noreferrer"><?=h($p['link_externo'])?></a></p><?php endif;?><div class="db-row"><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="acao" value="curtir"><input type="hidden" name="id_publicacao" value="<?=$p['id_publicacao']?>"><button class="db-btn secondary" type="submit"><?=$p['curtiu']?'♥ Curtido':'♡ Curtir'?> · <?=$p['total_curtidas']?></button></form><span class="db-small"><?=$p['total_comentarios']?> comentário(s)</span></div><div class="db-comments"><?php $cs=$pdo->prepare('SELECT c.*,u.nome,u.sobrenome FROM comentarios c LEFT JOIN usuarios u ON u.id_usuario=c.id_usuario WHERE c.id_publicacao=? ORDER BY c.data_criacao ASC LIMIT 20');$cs->execute([$p['id_publicacao']]);foreach($cs->fetchAll() as $c):?><div class="db-comment"><b><?=h(trim(($c['nome']??'Membro removido').' '.($c['sobrenome']??'')))?>:</b> <?=h($c['texto'])?> <span class="db-small">· <?=h(e_data($c['data_criacao']))?></span></div><?php endforeach;?><form class="db-form" method="post" style="margin-top:10px"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="acao" value="comentar"><input type="hidden" name="id_publicacao" value="<?=$p['id_publicacao']?>"><label>Adicionar comentário<input name="texto" maxlength="3000" required placeholder="Escreva um comentário..."></label><button class="db-btn secondary" type="submit">Comentar</button></form></div></article><?php endforeach;?><?php if(!$posts):?><div class="db-card db-empty">Ainda não há publicações. Seja o primeiro a compartilhar algo.</div><?php endif;?></section><aside><div class="db-card"><h3>Seu perfil</h3><div class="db-name"><?=h($eu['nome'].' '.$eu['sobrenome'])?></div><p class="db-muted"><?=h($eu['biografia']??'Adicione uma biografia para se apresentar à comunidade.')?></p><a class="db-btn secondary" href="?page=perfil">Editar perfil</a></div><div class="db-card"><h3>Membros para conhecer</h3><?php $s=$pdo->prepare("SELECT u.id_usuario,u.nome,u.sobrenome,p.nivel_experiencia FROM usuarios u LEFT JOIN perfis p ON p.id_usuario=u.id_usuario WHERE u.id_usuario<>? AND u.status_conta='ativa' AND NOT EXISTS (SELECT 1 FROM bloqueios b WHERE (b.id_usuario_bloqueador=u.id_usuario AND b.id_usuario_bloqueado=?) OR (b.id_usuario_bloqueador=? AND b.id_usuario_bloqueado=u.id_usuario)) ORDER BY u.data_criacao DESC LIMIT 6");$s->execute([$id,$id,$id]);$membros=$s->fetchAll();foreach($membros as $m):?><div class="db-item" style="margin-bottom:9px"><div class="db-name"><?=h($m['nome'].' '.$m['sobrenome'])?></div><div class="db-small"><?=h($m['nivel_experiencia']??'Membro')?></div><form method="post" style="margin-top:9px"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="acao" value="solicitar_conexao"><input type="hidden" name="id_usuario" value="<?=$m['id_usuario']?>"><button class="db-btn secondary" type="submit">+ Conectar</button></form></div><?php endforeach;?><?php if(!$membros):?><p class="db-muted">Novos membros aparecerão aqui.</p><?php endif;?></div></aside></div>
<?php elseif($page==='perfil'): ?>
<?php $s=$pdo->prepare('SELECT * FROM perfis WHERE id_usuario=?');$s->execute([$id]);$perfil=$s->fetch()?:[];$s=$pdo->prepare('SELECT COUNT(*) FROM conexoes WHERE status_conexao=\'aceita\' AND (id_usuario_solicitante=? OR id_usuario_destinatario=?)');$s->execute([$id,$id]);$totalConexoes=(int)$s->fetchColumn();$s=$pdo->prepare('SELECT codigo_convite,status_convite,data_expiracao FROM convites WHERE id_usuario_criador=? ORDER BY id_convite DESC');$s->execute([$id]);$meusConvites=$s->fetchAll();?>
<div class="db-grid"><section class="db-card"><h2>Editar informações</h2><form class="db-form" method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="acao" value="salvar_perfil"><div class="db-two"><label>Nome<input value="<?=h($eu['nome'])?>" disabled></label><label>Sobrenome<input value="<?=h($eu['sobrenome'])?>" disabled></label></div><label>Biografia<textarea name="biografia" maxlength="3000" placeholder="Conte um pouco sobre você..."><?=h($perfil['biografia']??'')?></textarea></label><div class="db-two"><label>Nível de experiência<select name="nivel_experiencia"><?php foreach(['iniciante'=>'Iniciante','estudante'=>'Estudante','intermediario'=>'Intermediário','avancado'=>'Avançado','outro'=>'Outro'] as $v=>$l):?><option value="<?=$v?>" <?=($perfil['nivel_experiencia']??'')===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><label>Localização<input name="localizacao" maxlength="150" value="<?=h($perfil['localizacao']??'')?>" placeholder="Ex.: Rio de Janeiro, RJ"></label></div><label>Tecnologias (separe por vírgula)<input name="tecnologias" value="<?=h(implode(', ',$tecnologiasUsuario))?>" placeholder="PHP, JavaScript, MySQL"></label><label>Interesses profissionais (máximo 3, separados por vírgula)<input name="interesses" value="<?=h(implode(', ',$interessesUsuario))?>" placeholder="Desenvolvimento web, IA"></label><label><span><input style="width:auto" type="checkbox" name="disponivel_projetos" value="1" <?=!empty($perfil['disponivel_projetos'])?'checked':''?>> Estou disponível para participar de projetos</span></label><button class="db-btn" type="submit">Salvar perfil</button></form></section><aside><div class="db-card"><h3>Resumo</h3><p><b><?=$totalConexoes?></b> conexões</p><p><b><?=count($tecnologiasUsuario)?></b> tecnologias</p><p><b><?=count($interessesUsuario)?></b> interesses</p></div><div class="db-card"><h3>Seus convites</h3><p class="db-muted">Convites disponíveis: compartilhe um código com alguém que queira entrar na DevBolha.</p><?php foreach($meusConvites as $c):?><div class="db-item" style="margin-bottom:8px"><b><?=h($c['codigo_convite'])?></b><div class="db-small"><?=h($c['status_convite'])?></div></div><?php endforeach;?><?php if(!$meusConvites):?><p class="db-muted">Nenhum convite registrado.</p><?php endif;?></div></aside></div>
<?php elseif($page==='conexoes'): ?>
<div class="db-grid"><section class="db-card"><h2>Solicitações recebidas</h2><?php $s=$pdo->prepare("SELECT c.*,u.nome,u.sobrenome FROM conexoes c JOIN usuarios u ON u.id_usuario=c.id_usuario_solicitante WHERE c.id_usuario_destinatario=? AND c.status_conexao='pendente' ORDER BY c.data_solicitacao DESC");$s->execute([$id]);$pendentes=$s->fetchAll();foreach($pendentes as $c):?><div class="db-item" style="margin-bottom:10px"><div class="db-name"><?=h($c['nome'].' '.$c['sobrenome'])?></div><div class="db-small"><?=h(e_data($c['data_solicitacao']))?></div><div class="db-row" style="margin-top:10px"><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="acao" value="responder_conexao"><input type="hidden" name="id_conexao" value="<?=$c['id_conexao']?>"><input type="hidden" name="resposta" value="aceita"><button class="db-btn">Aceitar</button></form><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="acao" value="responder_conexao"><input type="hidden" name="id_conexao" value="<?=$c['id_conexao']?>"><input type="hidden" name="resposta" value="recusada"><button class="db-btn secondary">Recusar</button></form></div></div><?php endforeach;?><?php if(!$pendentes):?><p class="db-empty">Você não tem solicitações pendentes.</p><?php endif;?></section><section class="db-card"><h2>Minhas conexões</h2><?php $s=$pdo->prepare("SELECT u.id_usuario,u.nome,u.sobrenome FROM conexoes c JOIN usuarios u ON u.id_usuario=IF(c.id_usuario_solicitante=?,c.id_usuario_destinatario,c.id_usuario_solicitante) WHERE (c.id_usuario_solicitante=? OR c.id_usuario_destinatario=?) AND c.status_conexao='aceita' AND NOT EXISTS (SELECT 1 FROM bloqueios b WHERE (b.id_usuario_bloqueador=u.id_usuario AND b.id_usuario_bloqueado=?) OR (b.id_usuario_bloqueador=? AND b.id_usuario_bloqueado=u.id_usuario)) ORDER BY u.nome");$s->execute([$id,$id,$id,$id,$id]);$conns=$s->fetchAll();foreach($conns as $c):?><div class="db-item" style="margin-bottom:9px"><div class="db-row"><div><div class="db-name"><?=h($c['nome'].' '.$c['sobrenome'])?></div><div class="db-small">Conexão aceita</div></div><a class="db-btn secondary" href="?page=mensagens&usuario=<?=$c['id_usuario']?>">Enviar mensagem</a></div><form method="post" style="margin-top:9px"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="acao" value="bloquear"><input type="hidden" name="id_usuario" value="<?=$c['id_usuario']?>"><button class="db-btn danger" type="submit" onclick="return confirm('Bloquear este membro? A conexão será encerrada.')">Bloquear</button></form></div><?php endforeach;?><?php if(!$conns):?><p class="db-empty">Suas conexões aceitas aparecerão aqui.</p><?php endif;?></section></div>
<?php elseif($page==='notificacoes'): ?>
<div class="db-card"><div class="db-row"><h2>Suas notificações</h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="acao" value="marcar_notificacoes"><button class="db-btn secondary">Marcar todas como lidas</button></form></div><?php $s=$pdo->prepare('SELECT n.*,u.nome,u.sobrenome FROM notificacoes n LEFT JOIN usuarios u ON u.id_usuario=n.id_usuario_origem WHERE n.id_usuario_destinatario=? ORDER BY n.data_criacao DESC LIMIT 100');$s->execute([$id]);$ns=$s->fetchAll();foreach($ns as $n):?><div class="db-item" style="margin-top:9px;<?=!$n['lida']?'border-color:#00b8d9':''?>"><div class="db-row"><b><?=h($n['mensagem'])?></b><span class="db-small"><?=h(e_data($n['data_criacao']))?></span></div><?php if($n['link_destino']):?><p><a class="db-link" href="<?=h($n['link_destino'])?>">Abrir ↗</a></p><?php endif;?></div><?php endforeach;?><?php if(!$ns):?><p class="db-empty">Você ainda não tem notificações.</p><?php endif;?></div>
<?php elseif($page==='projetos'): ?>
<div class="db-card"><h2>Criar projeto</h2><form class="db-form" method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="acao" value="criar_projeto"><div class="db-two"><label>Nome do projeto<input name="nome_projeto" maxlength="150" required></label><label>Tecnologias (separadas por vírgula)<input name="tecnologias" placeholder="PHP, MySQL, JavaScript"></label></div><label>Descrição<textarea name="descricao" required maxlength="10000"></textarea></label><label>Objetivos<textarea name="objetivos" maxlength="3000"></textarea></label><div class="db-two"><label>Repositório<input type="url" name="link_repositorio" placeholder="https://github.com/..."></label><label>Demonstração<input type="url" name="link_demonstracao" placeholder="https://..."></label></div><button class="db-btn">Publicar projeto</button></form></div>
<?php $s=$pdo->query("SELECT p.*,u.nome,u.sobrenome,(SELECT COUNT(*) FROM participantes_projeto pp WHERE pp.id_projeto=p.id_projeto AND pp.status_participacao='ativo') total_membros FROM projetos p LEFT JOIN usuarios u ON u.id_usuario=p.id_usuario_criador ORDER BY p.data_criacao DESC");$projs=$s->fetchAll();foreach($projs as $p):?><article class="db-card"><div class="db-row"><h2 style="margin:0"><?=h($p['nome_projeto'])?></h2><span class="db-tag"><?=h(str_replace('_',' ',$p['status_projeto']))?></span></div><p class="db-muted">Criado por <?=h(trim(($p['nome']??'Membro removido').' '.($p['sobrenome']??'')))?> · <?=$p['total_membros']?> participante(s)</p><p style="white-space:pre-wrap"><?=h($p['descricao'])?></p><?php if($p['objetivos']):?><p><b>Objetivos:</b> <?=h($p['objetivos'])?></p><?php endif;?><?php $s=$pdo->prepare('SELECT t.nome_tecnologia FROM tecnologias_projeto tp JOIN tecnologias t ON t.id_tecnologia=tp.id_tecnologia WHERE tp.id_projeto=?');$s->execute([$p['id_projeto']]);$tags=array_column($s->fetchAll(),'nome_tecnologia');if($tags):?><div class="db-tags"><?php foreach($tags as $t):?><span class="db-tag"><?=h($t)?></span><?php endforeach;?></div><?php endif;?><?php if($p['link_repositorio']):?><p><a class="db-link" href="<?=h($p['link_repositorio'])?>" target="_blank" rel="noopener noreferrer">Repositório ↗</a></p><?php endif;?><?php if($p['link_demonstracao']):?><p><a class="db-link" href="<?=h($p['link_demonstracao'])?>" target="_blank" rel="noopener noreferrer">Demonstração ↗</a></p><?php endif;?><?php if((int)$p['id_usuario_criador']!==$id && in_array($p['status_projeto'],['planejamento','em_andamento'],true)):?><?php $part=$pdo->prepare("SELECT status_participacao FROM participantes_projeto WHERE id_projeto=? AND id_usuario=?");$part->execute([$p['id_projeto'],$id]);$participacao=$part->fetchColumn();if($participacao==='ativo'):?><form method="post" style="margin-top:12px"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="acao" value="sair_projeto"><input type="hidden" name="id_projeto" value="<?=$p['id_projeto']?>"><button class="db-btn secondary" type="submit">Sair da equipe</button></form><?php else:?><form class="db-form" method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="acao" value="candidatar"><input type="hidden" name="id_projeto" value="<?=$p['id_projeto']?>"><label>Mensagem de candidatura (opcional)<input name="mensagem" maxlength="2000" placeholder="Por que você quer participar?"></label><button class="db-btn">Candidatar-se</button></form><?php endif;?><?php endif;?><?php if((int)$p['id_usuario_criador']===$id):?><hr class="db-divider"><details><summary>Editar projeto</summary><form class="db-form" method="post" style="margin-top:12px"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="acao" value="atualizar_projeto"><input type="hidden" name="id_projeto" value="<?=$p['id_projeto']?>"><label>Nome<input name="nome_projeto" maxlength="150" required value="<?=h($p['nome_projeto'])?>"></label><label>Descrição<textarea name="descricao" required maxlength="10000"><?=h($p['descricao'])?></textarea></label><label>Objetivos<textarea name="objetivos" maxlength="3000"><?=h($p['objetivos']??'')?></textarea></label><div class="db-two"><label>Repositório<input type="url" name="link_repositorio" value="<?=h($p['link_repositorio']??'')?>"></label><label>Demonstração<input type="url" name="link_demonstracao" value="<?=h($p['link_demonstracao']??'')?>"></label></div><label>Status<select name="status_projeto"><?php foreach(['planejamento'=>'Planejamento','em_andamento'=>'Em andamento','concluido'=>'Concluído','cancelado'=>'Cancelado'] as $v=>$l):?><option value="<?=$v?>" <?=$p['status_projeto']===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><button class="db-btn">Salvar alterações</button></form></details><h3>Candidaturas</h3><?php $s=$pdo->prepare("SELECT c.*,u.nome,u.sobrenome FROM candidatura_projetos c JOIN usuarios u ON u.id_usuario=c.id_usuario WHERE c.id_projeto=? ORDER BY c.data_candidatura DESC");$s->execute([$p['id_projeto']]);$cands=$s->fetchAll();foreach($cands as $c):?><div class="db-item" style="margin-bottom:8px"><b><?=h($c['nome'].' '.$c['sobrenome'])?></b> · <?=h($c['status_candidatura'])?><?php if($c['mensagem']):?><p><?=h($c['mensagem'])?></p><?php endif;?><?php if($c['status_candidatura']==='pendente'):?><div class="db-row"><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="acao" value="responder_candidatura"><input type="hidden" name="id_projeto" value="<?=$p['id_projeto']?>"><input type="hidden" name="id_usuario" value="<?=$c['id_usuario']?>"><input type="hidden" name="resposta" value="aprovada"><button class="db-btn">Aprovar</button></form><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="acao" value="responder_candidatura"><input type="hidden" name="id_projeto" value="<?=$p['id_projeto']?>"><input type="hidden" name="id_usuario" value="<?=$c['id_usuario']?>"><input type="hidden" name="resposta" value="recusada"><button class="db-btn secondary">Recusar</button></form></div><?php endif;?></div><?php endforeach;?><?php if(!$cands):?><p class="db-muted">Nenhuma candidatura até agora.</p><?php endif;?><?php endif;?></article><?php endforeach;?><?php if(!$projs):?><div class="db-card db-empty">Ainda não há projetos cadastrados.</div><?php endif;?>
<?php elseif($page==='mensagens'): ?>
<?php $alvo=(int)($_GET['usuario']??0);$s=$pdo->prepare("SELECT u.id_usuario,u.nome,u.sobrenome FROM conexoes c JOIN usuarios u ON u.id_usuario=IF(c.id_usuario_solicitante=?,c.id_usuario_destinatario,c.id_usuario_solicitante) WHERE (c.id_usuario_solicitante=? OR c.id_usuario_destinatario=?) AND c.status_conexao='aceita' AND NOT EXISTS (SELECT 1 FROM bloqueios b WHERE (b.id_usuario_bloqueador=u.id_usuario AND b.id_usuario_bloqueado=?) OR (b.id_usuario_bloqueador=? AND b.id_usuario_bloqueado=u.id_usuario)) ORDER BY u.nome");$s->execute([$id,$id,$id,$id,$id]);$listaConexoes=$s->fetchAll();?><div class="db-grid"><section class="db-card"><h2>Conversas</h2><?php foreach($listaConexoes as $c):?><div class="db-item" style="margin-bottom:8px"><a class="db-link" href="?page=mensagens&usuario=<?=$c['id_usuario']?>"><?=h($c['nome'].' '.$c['sobrenome'])?></a></div><?php endforeach;?><?php if(!$listaConexoes):?><p class="db-muted">Você precisa de conexões aceitas para enviar mensagens.</p><?php endif;?></section><section class="db-card"><?php $destino=null;foreach($listaConexoes as $c)if((int)$c['id_usuario']===$alvo)$destino=$c;if($destino):?><h2><?=h($destino['nome'].' '.$destino['sobrenome'])?></h2><?php $s=$pdo->prepare('SELECT * FROM mensagens WHERE ((id_remetente=? AND id_destinatario=?) OR (id_remetente=? AND id_destinatario=?)) ORDER BY data_envio ASC LIMIT 200');$s->execute([$id,$alvo,$alvo,$id]);foreach($s->fetchAll() as $m):?><div class="db-message <?=(int)$m['id_remetente']===$id?'mine':''?>"><?=h($m['texto'])?><div class="db-small"><?=h(e_data($m['data_envio']))?></div></div><?php if((int)$m['id_destinatario']===$id && !$m['data_leitura'])$pdo->prepare('UPDATE mensagens SET data_leitura=NOW() WHERE id_mensagem=?')->execute([$m['id_mensagem']]);endforeach;?><form class="db-form" method="post" style="margin-top:18px"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="acao" value="enviar_mensagem"><input type="hidden" name="id_destinatario" value="<?=$alvo?>"><label>Mensagem<textarea name="texto" required maxlength="10000"></textarea></label><button class="db-btn">Enviar mensagem</button></form><?php else:?><div class="db-empty">Selecione uma conexão à esquerda para abrir a conversa.</div><?php endif;?></section></div>
<?php elseif($page==='admin'): ?>
<?php if($eu['tipo_usuario']!=='administrador'):?><div class="db-card db-empty">Você não tem permissão para acessar esta área.</div><?php else:?><div class="db-grid"><div class="db-card"><h2>Resumo da comunidade</h2><?php foreach([['Membros',"SELECT COUNT(*) FROM usuarios WHERE status_conta='ativa'"],['Publicações','SELECT COUNT(*) FROM publicacoes'],['Projetos','SELECT COUNT(*) FROM projetos'],['Denúncias pendentes',"SELECT COUNT(*) FROM denuncias WHERE status_denuncia='pendente'"]] as [$label,$sql]):?><div class="db-row" style="padding:10px 0;border-bottom:1px solid var(--db-line)"><span><?=h($label)?></span><b><?=$pdo->query($sql)->fetchColumn()?></b></div><?php endforeach;?></div><div class="db-card"><h2>Denúncias recentes</h2><?php $ds=$pdo->query('SELECT d.*,u.nome,u.sobrenome FROM denuncias d LEFT JOIN usuarios u ON u.id_usuario=d.id_usuario_denunciante ORDER BY d.data_criacao DESC LIMIT 50')->fetchAll();foreach($ds as $d):?><div class="db-item" style="margin-bottom:8px"><b><?=h($d['tipo_alvo'])?> #<?=h($d['id_alvo'])?></b><div class="db-small"><?=h($d['motivo'])?> · <?=h($d['status_denuncia'])?> · <?=h(e_data($d['data_criacao']))?></div><p><?=h($d['descricao']??'')?></p></div><?php endforeach;?><?php if(!$ds):?><p class="db-muted">Nenhuma denúncia registrada.</p><?php endif;?></div></div><?php endif;?>
<?php endif;?>
<footer class="db-small" style="padding:24px 0;text-align:center">© <?=date('Y')?> DevBolha · Construa junto.</footer></main></div></div></body></html>
